// === 1. Sentry 初始化 ===
import * as Sentry from '@sentry/react';

Sentry.init({
  dsn: 'https://xxx@sentry.io/xxx',
  environment: process.env.NODE_ENV,
  release: process.env.npm_package_version,
  integrations: [
    Sentry.browserTracingIntegration(),
    Sentry.replayIntegration()
  ],
  tracesSampleRate: 0.1,
  replaysSessionSampleRate: 0.1,
  replaysOnErrorSampleRate: 1.0,
  beforeSend(event) {
    // 过滤已知无意义错误
    if (event.exception) {
      const error = event.exception.values[0];
      if (error?.value?.includes('Script error')) return null;
    }
    // 脱敏 URL 中的 token
    if (event.request?.url) {
      event.request.url = event.request.url.replace(/token=[^&]+/, 'token=***');
    }
    return event;
  }
});

// === 2. 全局错误捕获（第一层：同步异常） ===
window.onerror = (msg, url, line, col, error) => {
  // Sentry SDK 内部已注册，通常不需要手动上报
  console.error('Global error:', { msg, url, line, col, error });
};

// === 3. 未处理 Promise rejection（第二层） ===
window.addEventListener('unhandledrejection', (event) => {
  // event.preventDefault() 阻止控制台报错，仅在上报逻辑中使用
  console.error('Unhandled rejection:', event.reason);
});

// === 4. 资源加载错误（第一层补充，捕获阶段） ===
document.addEventListener('error', (event) => {
  if (event.target.tagName) {
    const url = event.target.src || event.target.href;
    console.error('Resource load failed:', url);
    // 上报资源加载失败
  }
}, true); // true = 捕获阶段，才能拿到资源错误

